import * as React from "react"
import { useMemo } from "react"
import { graphql, Link } from "gatsby"
import { GatsbyImage, getImage, IGatsbyImageData } from "gatsby-plugin-image"

import "../scss/main.scss"

import Header from "../components/Header"

const SHOWCASE_COUNT = 9

interface ImageNode {
  name: string
  childImageSharp: {
    gatsbyImageData: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    profileImage: {
      childImageSharp: {
        gatsbyImageData: IGatsbyImageData
      }
    }
    photography: { nodes: ImageNode[] }
    art: { nodes: ImageNode[] }
    design: { nodes: ImageNode[] }
  }
}

type ShowcaseImage = ImageNode & { linkTo: string }

const Index: React.FC<PageProps> = ({ data }) => {
  const profileImage = getImage(data.profileImage.childImageSharp.gatsbyImageData)

  const showcaseImages = useMemo(() => {
    const combined: ShowcaseImage[] = [
      ...data.photography.nodes.map(n => ({ ...n, linkTo: "/photography" })),
      ...data.art.nodes.map(n => ({ ...n, linkTo: "/creations/art" })),
      ...data.design.nodes.map(n => ({ ...n, linkTo: "/creations" })),
    ]

    // Fisher-Yates shuffle
    for (let i = combined.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[combined[i], combined[j]] = [combined[j], combined[i]]
    }

    return combined.slice(0, SHOWCASE_COUNT)
  }, [data.photography.nodes, data.art.nodes, data.design.nodes])

  return (
    <div className="container">
      <Header />
      <div className="home-hero">
        <div className="home-content">
          <div className="profile-image-container">
            {profileImage && (
              <GatsbyImage
                image={profileImage}
                alt="Jayne Hepburn"
                className="profile-image"
              />
            )}
          </div>
          <div className="bio-container">
            <h1>Hi, I'm Jayne</h1>
            <p className="bio-text">
              Designer, developer, photographer, and artist — exploring
              creativity across mediums and bringing ideas to life through
              code, camera, and canvas.
            </p>
          </div>
        </div>
      </div>

      <div className="showcase-section">
        <div className="showcase-header">
          <h2>Selected Works</h2>
        </div>
        <div className="masonry-gallery">
          {showcaseImages.map((img, index) => {
            const image = getImage(img.childImageSharp.gatsbyImageData)
            if (!image) return null

            return (
              <Link key={`${img.name}-${index}`} to={img.linkTo} className="gallery-item">
                <GatsbyImage
                  image={image}
                  alt={img.name}
                  className="gallery-thumb"
                />
              </Link>
            )
          })}
        </div>
      </div>
    </div>
  )
}

export const query = graphql`
  query IndexShowcaseQuery {
    profileImage: file(
      sourceInstanceName: { eq: "profile" }
      relativePath: { eq: "me.png" }
    ) {
      childImageSharp {
        gatsbyImageData(
          width: 800
          placeholder: BLURRED
          transformOptions: { fit: COVER, cropFocus: CENTER }
        )
      }
    }
    photography: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { ne: "" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(width: 400, placeholder: BLURRED)
        }
      }
    }
    art: allFile(
      filter: { sourceInstanceName: { eq: "art" } }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(width: 400, placeholder: BLURRED)
        }
      }
    }
    design: allFile(
      filter: {
        sourceInstanceName: { eq: "design" }
        relativeDirectory: { ne: "" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(width: 400, placeholder: BLURRED)
        }
      }
    }
  }
`

export default Index
